#include <bits/stdc++.h>
using namespace std;
using int64 = long long;

int64 normalize(int64 x) {
    // Remove factors of cubes from x
    for (int64 p = 2; p * p * p <= x; p++) {
        while (x % (p * p * p) == 0) {
            x /= (p * p * p);
        }
    }
    return x;
}

int64 conflict(int64 x) {
    // find y such that x * y is a perfect cube, with y normalized
    int64 y = 1;
    // Factor x and build y
    for (int64 p = 2; p * p <= x; p++) {
        if (x % p == 0) {
            int cnt = 0;
            while (x % p == 0) {
                x /= p;
                cnt++;
            }
            cnt %= 3; // because x is normalized, cnt is 1 or 2
            int need = (3 - cnt) % 3;
            for (int i = 0; i < need; i++) {
                y *= p;
                if (y > 1e10) return -1; // prevent overflow
            }
        }
    }
    if (x > 1) {
        // x is a prime with exponent 1, need exponent 2 for cube
        y *= x * x;
        if (y > 1e10) return -1;
    }
    return y;
}

