using int64 = long long;

static long long cube_root_floor(long long x) {
    long long l = 0, r = 1000000 + 5; // enough for (1e18)^(1/3)
    while (r - l > 1) {
        long long m = (l + r) / 2;
        __int128 v = (__int128)m * m * m;
        if (v <= x) l = m;
        else r = m;
    }
    return l;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    unordered_map<long long, long long> cnt;
    cnt.reserve(N * 2);

    for (int i = 0; i < N; i++) {
        long long x;
        cin >> x;

        long long a = x;
        long long norm = 1;
        long long comp = 1;

        for (long long p = 2; p * p * p <= a; p++) {
            int e = 0;
            while (a % p == 0) {
                a /= p;
                e++;
            }
            e %= 3;
            if (e == 1) {
                norm *= p;
                comp *= p * p;
            } else if (e == 2) {
                norm *= p * p;
                comp *= p;
            }
        }

        // Remaining a has no prime cube divisor.
        // So a is one of:
        // 1
        // p
        // p^2
        // p*q (distinct primes)
        if (a > 1) {
            long long r = cube_root_floor(a);
            if ((__int128)r * r * r == a) {
                // Actually impossible here except a=1, but keep safe.
            } else {
                long long s = sqrtl((long double)a);
                while ((__int128)(s + 1) * (s + 1) <= a) s++;
                while ((__int128)s * s > a) s--;
                if ((__int128)s * s == a) {
                    // a = p^2
                    norm *= a;
                    if ((__int128)comp * s <= (long long)4e18) comp *= s;
                    else comp = (long long)4e18;
                } else {
                    // a is squarefree in remaining part: prime or product of two distinct primes
                    norm *= a;
                    if ((__int128)comp * a * a <= (long long)4e18) comp *= a * a;
                    else comp = (long long)4e18;
                }
            }
        }

        cnt[norm]++;
    }

    long long ans = 0;
    unordered_set<long long> used;
    used.reserve(cnt.size() * 2);

    for (auto &kv : cnt) {
        long long x = kv.first;
        if (used.count(x)) continue;

        // recompute complement of x
        long long a = x;
        long long comp = 1;
        for (long long p = 2; p * p * p <= a; p++) {
            int e = 0;
            while (a % p == 0) {
                a /= p;
                e++;
            }
            e %= 3;
            if (e == 1) comp *= p * p;
            else if (e == 2) comp *= p;
        }
        if (a > 1) {
            long long s = sqrtl((long double)a);
            while ((__int128)(s + 1) * (s + 1) <= a) s++;
            while ((__int128)s * s > a) s--;
            if ((__int128)s * s == a) {
                if ((__int128)comp * s <= (long long)4e18) comp *= s;
                else comp = (long long)4e18;
            } else {
                if ((__int128)comp * a * a <= (long long)4e18) comp *= a * a;
                else comp = (long long)4e18;
            }
        }

        if (x == 1) {
            ans += 1; // all perfect cubes reduce to 1, can choose at most one
            used.insert(1);
        } else {
            long long c1 = cnt[x];
            long long c2 = cnt.count(comp) ? cnt[comp] : 0;
            ans += max(c1, c2);
            used.insert(x);
            used.insert(comp);
        }
    }

    cout << ans << '\n';
    return 0;
}

