// Prime sieve up to 1000 (since cube root of 1e9 is 1000)
int primes[200], pcnt;
int is_prime[1001];

void sieve() {
    for (int i = 2; i <= 1000; i++) is_prime[i] = 1;
    for (int i = 2; i <= 1000; i++) {
        if (is_prime[i]) {
            primes[pcnt++] = i;
            for (int j = i*i; j <= 1000; j += i) is_prime[j] = 0;
        }
    }
}

// Convert number to cube-free form and its complement
void normalize(int x, ll *norm, ll *comp) {
    *norm = 1;
    *comp = 1;
    for (int i = 0; i < pcnt && primes[i] * primes[i] <= x; i++) {
        int p = primes[i];
        int cnt = 0;
        while (x % p == 0) {
            x /= p;
            cnt++;
        }
        cnt %= 3;
        if (cnt == 1) {
            *norm *= p;
            *comp *= (ll)p * p;
        } else if (cnt == 2) {
            *norm *= (ll)p * p;
            *comp *= p;
        }
    }
    if (x > 1) {
        // x is a prime > 1000, exponent 1
        *norm *= x;
        *comp *= (ll)x * x;
    }
    // Avoid overflow in comp by capping
    if (*comp > 1000000000000LL) *comp = 1000000000001LL;
}

int main() {
    sieve();
    scanf("%d", &N);
    for (int i = 0; i < N; i++) {
        scanf("%d", &A[i]);
    }

    // Map from normalized form to count
    // We'll use a simple array of pairs since N <= 1e5
    ll norms[MAXN], comps[MAXN];
    int used[MAXN] = {0};
    int ans = 0;

    for (int i = 0; i < N; i++) {
        normalize(A[i], &norms[i], &comps[i]);
    }

    // Count frequencies of each norm
    // Sort indices by norm for grouping
    int idx[MAXN];
    for (int i = 0; i < N; i++) idx[i] = i;

    // Simple sort by norm
    for (int i = 0; i < N; i++) {
        for (int j = i+1; j < N; j++) {
            if (norms[idx[i]] > norms[idx[j]]) {
                int tmp = idx[i];
                idx[i] = idx[j];
                idx[j] = tmp;
            }
        }
    }

    for (int i = 0; i < N; i++) {
        if (used[idx[i]]) continue;
        int cur = idx[i];
        int cnt_cur = 0, cnt_comp = 0;
        ll comp = comps[cur];
        ll norm_cur = norms[cur];
        for (int j = i; j < N; j++) {
            int k = idx[j];
            if (norms[k] == norm_cur && !used[k]) cnt_cur++;
            else break;
        }
        // Find complement group
        int comp_idx = -1;
        for (int j = 0; j < N; j++) {
            if (norms[idx[j]] == comp && !used[idx[j]]) {
                comp_idx = j;
                break;
            }
        }
        if (comp_idx >= 0) {
            for (int j = comp_idx; j < N; j++) {
                int k = idx[j];
                if (norms[k] == comp && !used[k]) cnt_comp++;
                else break;
            }
        }

        if (norm_cur == 1) {
            // perfect cube case
            ans += 1;
            // mark all with norm_cur = 1 as used
            for (int j = i; j < N; j++) {
                int k = idx[j];
                if (norms[k] == 1) used[k] = 1;
                else break;
            }
        } else if (norm_cur == comp) {
            // self-complementary (norm^2 == 1 mod cube? rare but possible if norm is cube itself? handled)
            ans += 1;
            for (int j = i; j < N; j++) {
                int k = idx[j];
                if (norms[k] == norm_cur) used[k] = 1;
                else break;
            }
        } else {
            ans += (cnt_cur > cnt_comp ? cnt_cur : cnt_comp);
            // mark both groups used
            for (int j = i; j < N; j++) {
                int k = idx[j];
                if (norms[k] == norm_cur) used[k] = 1;
                else break;
            }
            if (comp_idx >= 0) {
                for (int j = comp_idx; j < N; j++) {
                    int k = idx[j];
                    if (norms[k] == comp) used[k] = 1;
                    else break;
                }
            }
        }
    }

    printf("%d\n", ans);
    return 0;
}

