Entry *table[HASHSZ];

unsigned int hash_str(const char *s) {
    unsigned int h = 5381;
    while (*s) h = h * 33 + (unsigned char)*s++;
    return h % HASHSZ;
}

int get(const char *key) {
    unsigned int h = hash_str(key);
    for (Entry *e = table[h]; e; e = e->next)
        if (!strcmp(e->key, key)) return e->val;
    return 0;
}

void set(const char *key, int val) {
    unsigned int h = hash_str(key);
    for (Entry *e = table[h]; e; e = e->next)
        if (!strcmp(e->key, key)) { e->val = val; return; }
    Entry *e = malloc(sizeof(Entry));
    strcpy(e->key, key);
    e->val = val;
    e->next = table[h];
    table[h] = e;
}

