typedef long long ll;

#define MAXP 1000000
#define HASH_SIZE 1048576

typedef struct {
    ll key;
    int val;
    char used;
} HashEntry;

static HashEntry hcnt[HASH_SIZE];
static HashEntry hid[HASH_SIZE];
static ll primes[80000];
static int pcnt = 0;

static unsigned long long splitmix64(unsigned long long x) {
    x += 0x9e3779b97f4a7c15ULL;
    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
    x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
    return x ^ (x >> 31);
}

static int hash_find(HashEntry *h, ll key) {
    unsigned long long x = splitmix64((unsigned long long)key);
    int idx = (int)(x & (HASH_SIZE - 1));
    while (h[idx].used && h[idx].key != key) idx = (idx + 1) & (HASH_SIZE - 1);
    return idx;
}

static int get_count(ll key) {
    int p = hash_find(hcnt, key);
    return hcnt[p].used ? hcnt[p].val : 0;
}

static void add_count(ll key) {
    int p = hash_find(hcnt, key);
    if (!hcnt[p].used) {
        hcnt[p].used = 1;
        hcnt[p].key = key;
        hcnt[p].val = 1;
    } else {
        hcnt[p].val++;
    }
}

static int get_id(ll key) {
    int p = hash_find(hid, key);
    return hid[p].used ? hid[p].val : -1;
}

static void set_id(ll key, int id) {
    int p = hash_find(hid, key);
    hid[p].used = 1;
    hid[p].key = key;
    hid[p].val = id;
}

static ll ipow_limit(ll a, int e, ll limit) {
    ll r = 1;
    while (e--) {
        if (a != 0 && r > limit / a) return limit + 1;
        r *= a;
    }
    return r;
}

