static ll icbrt_ll(ll x) {
    ll l = 0, r = 2000000;
    while (l < r) {
        ll m = (l + r + 1) >> 1;
        __int128 v = (__int128)m * m * m;
        if (v <= x) l = m;
        else r = m - 1;
    }
    return l;
}

static int is_cube_ll(ll x) {
    ll r = icbrt_ll(x);
    return (__int128)r * r * r == x;
}

