public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        long[] s = new long[N];
        for (int i = 0; i < N; i++) {
            s[i] = sc.nextLong();
        }

        Map<Long, Integer> countMap = new HashMap<>();
        Map<Long, Long> complementMap = new HashMap<>();

        for (long x : s) {
            long normal = 1;
            long comp = 1;
            long temp = x;
            for (long p = 2; p * p * p <= temp; p++) {
                if (temp % p == 0) {
                    int exp = 0;
                    while (temp % p == 0) {
                        temp /= p;
                        exp++;
                    }
                    exp %= 3;
                    if (exp == 1) {
                        normal *= p;
                        comp *= p * p;
                    } else if (exp == 2) {
                        normal *= p * p;
                        comp *= p;
                    }
                }
            }
            // leftover temp is either 1, prime, or product of two primes
            if (temp > 1) {
                long sqrt = (long) Math.sqrt(temp);
                if (sqrt * sqrt == temp) {
                    // temp = p^2
                    normal *= temp;
                    comp *= sqrt;
                } else {
                    // temp is prime
                    normal *= temp;
                    comp *= temp * temp;
                }
            }

            countMap.put(normal, countMap.getOrDefault(normal, 0) + 1);
            complementMap.put(normal, comp);
        }

        int ans = 0;
        Set<Long> visited = new HashSet<>();

        for (long key : countMap.keySet()) {
            if (visited.contains(key)) continue;
            long comp = complementMap.get(key);
            if (key == 1) {
                // special case: perfect cubes, only one can be taken
                ans += 1;
                visited.add(key);
            } else if (comp == key) {
                // self-complementary
                ans += 1;
                visited.add(key);
            } else {
                int cntKey = countMap.get(key);
                int cntComp = countMap.getOrDefault(comp, 0);
                ans += Math.max(cntKey, cntComp);
                visited.add(key);
                visited.add(comp);
            }
        }

        System.out.println(ans);
    }
}

import java.util.*;

public class Main {
    static Map<Long, Integer> factorize(long n) {
        Map<Long, Integer> map = new TreeMap<>();
        for (long p = 2; p * p <= n; p++) {
            while (n % p == 0) {
                map.merge(p, 1, Integer::sum);
                n /= p;
            }
        }
        if (n > 1) map.put(n, 1);
        return map;
    }

    static String getKey(long n) {
        Map<Long, Integer> f = factorize(n);
        StringBuilder sb = new StringBuilder();
        for (Map.Entry<Long, Integer> e : f.entrySet()) {
            int r = e.getValue() % 3;
            if (r != 0) sb.append(e.getKey()).append("^").append(r).append("*");
        }
        return sb.toString();
    }

    static String complement(String key) {
        // parse and flip 1->2, 2->1
        if (key.isEmpty()) return key;
        String[] parts = key.split("\\*");
        TreeMap<Long, Integer> map = new TreeMap<>();
        for (String p : parts) {
            if (p.isEmpty()) continue;
            String[] kv = p.split("\\^");
            long prime = Long.parseLong(kv[0]);
            int exp = Integer.parseInt(kv[1]);
            map.put(prime, 3 - exp);
        }
        StringBuilder sb = new StringBuilder();
        for (Map.Entry<Long, Integer> e : map.entrySet()) {
            sb.append(e.getKey()).append("^").append(e.getValue()).append("*");
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        Map<String, Integer> count = new HashMap<>();
        for (int i = 0; i < N; i++) {
            long s = sc.nextLong();
            String key = getKey(s);
            count.merge(key, 1, Integer::sum);
        }
        Set<String> visited = new HashSet<>();
        long ans = 0;
        for (String key : count.keySet()) {
            if (visited.contains(key)) continue;
            String comp = complement(key);
            if (key.equals(comp)) { // perfect cube signature
                ans += 1;
            } else {
                int c1 = count.getOrDefault(key, 0);
                int c2 = count.getOrDefault(comp, 0);
                ans += Math.max(c1, c2);
                visited.add(comp);
            }
            visited.add(key);
        }
        System.out.println(ans);
    }
}

