import java.util.*;

/*
 * AtCoder AGC003 D - Anticube
 *
 * Idea:
 * For each number x, factorize it and reduce exponents modulo 3.
 * Let a = canonical cube-free form of x:
 *   x = (cube) * Π p^e , where e in {0,1,2}
 *
 * We need choose maximum subset such that for any two chosen numbers u,v,
 * u*v is NOT a perfect cube.
 *
 * Two reduced forms a and b multiply to a cube iff for every prime p,
 * exp_a(p)+exp_b(p) ≡ 0 (mod 3). So b is uniquely determined from a:
 *   if a has p^1 then b needs p^2
 *   if a has p^2 then b needs p^1
 *
 * Let partner(a) = complement form.
 * Then from each pair {a, partner(a)} we can choose numbers only from one side.
 * So answer is:
 *   1 if there exists any number whose reduced form is 1
 *   plus for each unordered pair {a,b}, a!=b, add max(cnt[a], cnt[b])
 *
 * Need careful factorization up to 1e10-ish? In original problem Ai <= 1e10.
 * We can factor by trial division using primes up to 1e5 because cube root(1e10)=2154,
 * but for exact reduced form we need more care after removing small prime factors:
 * after trial division by primes up to 1e5, remainder can be:
 *   1
 *   prime
 *   prime^2
 *   product of two primes
 * For cube-free reduction/complement, standard approach:
 *   factor by primes up to 1e5 while counting exp mod 3.
 *   For remaining n:
 *      if n is perfect square of prime q: exponent 2
 *      else if n is prime: exponent 1
 *      else exponent 1 of composite leftover (treated as a "big prime" key)
 * This works because after removing small primes, leftover cannot contain any cube factor,
 * and if composite non-square, it behaves as product of distinct large primes each exp 1;
 * for complement possibly exceeds 1e10. If complement gets too large (>1e10) we can mark
 * impossible-to-match sentinel, but in this implementation we use BigInteger-free long and
 * overflow-safe bound INF = 4e18. Since actual matching only matters among existing reduced
 * forms from input, and partner of such composite leftovers won't appear unless representable.
 *
 * Simpler robust method:
 * store reduced form and complement as long, but if complement would overflow or exceed 1e10,
 * set to -1, meaning no partner can exist in input range. Since Ai <= 1e10 in this task.
 */

public class Main {
    static final long LIMIT_A = 10_000_000_000L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        long[] a = new long[N];
        for (int i = 0; i < N; i++) a[i] = fs.nextLong();

        int maxP = 100000;
        List<Integer> primes = sieve(maxP);

        HashMap<Long, Integer> cnt = new HashMap<>();

        for (long x : a) {
            long key = reduceCubeFree(x, primes);
            cnt.put(key, cnt.getOrDefault(key, 0) + 1);
        }

        long ans = 0;
        HashSet<Long> used = new HashSet<>();

        if (cnt.containsKey(1L)) {
            ans += 1;
            used.add(1L);
        }

        for (long key : cnt.keySet()) {
            if (used.contains(key) || key == 1L) continue;
            long comp = complement(key, primes);
            int c1 = cnt.getOrDefault(key, 0);
            int c2 = (comp == -1 ? 0 : cnt.getOrDefault(comp, 0));
            ans += Math.max(c1, c2);
            used.add(key);
            if (comp != -1) used.add(comp);
        }

        System.out.println(ans);
    }

    static long reduceCubeFree(long x, List<Integer> primes) {
        long n = x;
        long res = 1;

        for (int p : primes) {
            long pp = (long) p * p * p;
            if (pp > n) break;
            if (n % p != 0) continue;
            int e = 0;
            while (n % p == 0) {
                n /= p;
                e++;
            }
            e %= 3;
            if (e == 1) res *= p;
            else if (e == 2) res *= (long) p * p;
        }

        if (n == 1) return res;

        long s = isPerfectSquare(n);
        if (s != -1 && isPrime(s)) {
            // n = p^2
            res *= n;
        } else if (isPrime(n)) {
            // n = p
            res *= n;
        } else {
            // n is product of distinct large primes with exp 1 each (or similar cube-free leftover)
            // just multiply it in as-is
            res *= n;
        }
        return res;
    }

    static long complement(long x, List<Integer> primes) {
        if (x == 1) return 1;
        long n = x;
        long res = 1;

        for (int p : primes) {
            long pp = (long) p * p;
            if (pp > n) break;
            if (n % p != 0) continue;
            int e = 0;
            while (n % p == 0) {
                n /= p;
                e++;
            }
            e %= 3;
            if (e == 1) {
                if (willOverflowMul(res, (long) p * p) || res * (long) p * p > LIMIT_A) return -1;
                res *= (long) p * p;
            } else if (e == 2) {
                if (willOverflowMul(res, p) || res * p > LIMIT_A) return -1;
                res *= p;
            }
        }

        if (n > 1) {
            long s = isPerfectSquare(n);
            if (s != -1 && isPrime(s)) {
                // n = p^2, need p
                if (willOverflowMul(res, s) || res * s > LIMIT_A) return -1;
                res *= s;
            } else {
                // n contributes exponent 1 for each prime factor, so complement needs square of n if prime,
                // or impossible within limit for composite leftover in input range.
                if (isPrime(n)) {
                    if (willOverflowMul(res, n) || willOverflowMul(res * n, n) || res * n * n > LIMIT_A) return -1;
                    res *= n * n;
                } else {
                    // composite leftover => complement would exceed input limit / not representable as existing reduced key
                    return -1;
                }
            }
        }
        return res;
    }

    static boolean willOverflowMul(long a, long b) {
        if (a == 0 || b == 0) return false;
        return a > Long.MAX_VALUE / b;
    }

    static long isPerfectSquare(long x) {
        long r = (long) Math.sqrt(x);
        while ((r + 1) * (r + 1) <= x) r++;
        while (r * r > x) r--;
        return r * r == x ? r : -1;
    }

    static boolean isPrime(long n) {
        if (n < 2) return false;
        if (n % 2 == 0) return n == 2;
        for (long i = 3; i * i <= n; i += 2) {
            if (n % i == 0) return false;
        }
        return true;
    }

    static List<Integer> sieve(int n) {
        boolean[] comp = new boolean[n + 1];
        ArrayList<Integer> ps = new ArrayList<>();
        for (int i = 2; i <= n; i++) {
            if (!comp[i]) {
                ps.add(i);
                if ((long) i * i <= n) {
                    for (int j = i * i; j <= n; j += i) comp[j] = true;
                }
            }
        }
        return ps;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            long sign = 1, val = 0;
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            if (c == '-') {
                sign = -1;
                c = read();
            }
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}

import sys
from collections import defaultdict
import math

def factor_cube_free(n):
    # returns tuple of (prime, exponent%3) for primes >0
    factors = defaultdict(int)
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors[d] += 1
            n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        factors[n] += 1
    # reduce exponents mod 3
    normal = []
    for p in sorted(factors):
        e = factors[p] % 3
        if e != 0:
            normal.append((p, e))
    return tuple(normal)

def complement_form(form):
    return tuple((p, (3 - e) % 3) for p, e in form)

def main():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    N = int(input_data[0])
    arr = list(map(int, input_data[1:]))

    count = defaultdict(int)
    for x in arr:
        f = factor_cube_free(x)
        count[f] += 1

    ans = 0
    used = set()
    for form, cnt in count.items():
        if form in used:
            continue
        comp = complement_form(form)
        if form == comp:
            # self complementary: can take at most 1
            ans += 1
        else:
            ans += max(cnt, count.get(comp, 0))
            used.add(comp)
        used.add(form)
    print(ans)

if __name__ == "__main__":
    main()
